    "questionAr": "موضع جسيم يعطى بالعلاقة $r(t) = (t^2 + 4t - 4)\\hat{c}\\text{ م}$. أوجد مقدار الإزاحة من $t = 0$ إلى $t = 1\\text{ ث}$.",
