    "questionAr": "يتحرك جسيم في خط مستقيم بحيث تعطى إزاحته $s$ (بالمتر) عند اللحظة $t$ (بالثانية) بالعلاقة $s(t) = 3t^2 - 12t + 5$. عند أي لحظة زمنية $t$ يسكن الجسيم لحظياً؟",
