    "questionAr": "يتحرك جسيمان في خط مستقيم بموضعين $x_1(t) = t^2 + 4$ و $x_2(t) = 5t$. إذا التقى الجسيمان عند $t = 1\\text{ ث}$، فأوجد لحظة لقائهما الثانية ($t > 1$).",
